//! The OPENUI LANG section's reference: the desktop's own generated file
//! (the web's `OPENUI_LANG_DOC` and `OPENUI_LANG_SECTION` in `prompts.py`).
//!
//! The section is the web's preamble followed by the generated OpenUI Lang
//! reference. The web reads `docs/prompt/openui-lang.md`, generated from its
//! `openuiLibrary.ts`; the desktop compiles in its own
//! `docs/prompt/openui-lang.md` (decision 17), generated by
//! `scripts/generate-openui-prompt.mjs` from `src/lib/agent/openuiLibrary.ts`,
//! the library the desktop's renderer draws with, and pinned to it by
//! `openuiLibrary.test.ts`. So the model is taught exactly the components the
//! desktop renders: the two differ from the web's where the desktop narrowed
//! the list components (D-022: no image, no action, no button, no URL).
//!
//! `sections.json` carries the web's section verbatim; the web's reference
//! starts at its generated banner, and everything from there on is replaced
//! here. Compiled in, the file can never be missing, so the web's "section
//! omitted, regenerate it" path has no desktop counterpart.

/// The generated reference, as committed.
pub(crate) const OPENUI_LANG_DOC: &str = include_str!("../../../../docs/prompt/openui-lang.md");

/// The key of the section the reference fills.
pub(crate) const OPENUI_LANG_KEY: &str = "openui_lang";

/// Where the web's generated reference begins inside its recorded section.
pub(crate) const WEB_DOC_BANNER: &str =
    "<!--\nGENERATED by frontend/scripts/generate-openui-prompt.mjs";

/// The web's section body with its reference replaced by the desktop's. A
/// body without the web's banner is returned unchanged (a test pins that the
/// recorded one has it, so a web change cannot slip the web's reference
/// through).
pub(crate) fn desktop_reference(web_body: &str) -> String {
    match web_body.find(WEB_DOC_BANNER) {
        Some(at) => format!("{}{}", &web_body[..at], reference()),
        None => web_body.to_string(),
    }
}

/// The reference as the model reads it: trimmed, with line feeds only. A
/// Windows checkout holds the file with CRLF; the web reads it with
/// universal newlines, so the prompt never carries a carriage return.
pub(crate) fn reference() -> String {
    OPENUI_LANG_DOC.trim().replace("\r\n", "\n")
}

/// The web's reference inside its recorded section body (what
/// [`desktop_reference`] replaces), for the fixture comparison.
#[cfg(test)]
pub(crate) fn web_reference(web_body: &str) -> Option<&str> {
    web_body.find(WEB_DOC_BANNER).map(|at| &web_body[at..])
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::agent::contract::tool::Surface;
    use crate::agent::prompts::{build_system_prompt, sections_for, SystemPrompt};

    fn section(surface: Surface) -> String {
        sections_for(surface, &[], None, None)
            .into_iter()
            .find(|s| s.key == OPENUI_LANG_KEY)
            .map(|s| s.render())
            .unwrap_or_else(|| panic!("no OPENUI LANG section on {:?}", surface))
    }

    /// Q-631, Q-632: the reference is there and whole, on chat and voice.
    #[test]
    fn the_generated_reference_is_present_and_not_a_stub() {
        for surface in [Surface::Chat, Surface::Voice] {
            let body = section(surface);
            assert!(body.len() > 4000, "{:?}: {} chars", surface, body.len());
            assert!(!body.contains("undefined"), "{:?}", surface);
            assert!(body.starts_with("OPENUI LANG: WHAT render_ui TAKES\nThis describes the `markup` argument of the render_ui tool."));
            assert!(body.contains(&reference()));
            assert!(!body.contains('\r'));
            assert!(body.contains("GENERATED by scripts/generate-openui-prompt.mjs"));
        }
    }

    /// P-024: the chart panel has no render_ui, so no OPENUI LANG section.
    #[test]
    fn the_chart_panel_is_not_taught_openui() {
        let prompt = build_system_prompt(&SystemPrompt {
            surface: Some(Surface::Chart),
            ..Default::default()
        });
        assert!(!prompt.contains("OPENUI LANG"));
    }

    /// D-022: the model is never taught an image, an action, a button or a
    /// URL, on any surface.
    #[test]
    fn the_prompt_teaches_no_url_button_action_or_image() {
        for surface in [Surface::Chat, Surface::Voice] {
            let body = section(surface);
            for taught in [
                "Button",
                "@OpenUrl",
                "ActionExpression",
                "image?:",
                "\"image\"",
                "https://",
                "http://",
            ] {
                assert!(!body.contains(taught), "{:?} teaches {}", surface, taught);
            }
        }
    }

    #[test]
    fn only_the_web_reference_is_replaced() {
        let web = "Preamble.\n\n<!--\nGENERATED by frontend/scripts/generate-openui-prompt.mjs x\n-->\n\nWEB-ONLY-REFERENCE";
        let swapped = desktop_reference(web);
        assert!(swapped.starts_with("Preamble.\n\n<!--\nGENERATED by scripts/"));
        assert!(swapped.ends_with(&reference()));
        assert!(!swapped.contains("WEB-ONLY-REFERENCE"));
        assert_eq!(
            web_reference(web).map(|r| r.ends_with("WEB-ONLY-REFERENCE")),
            Some(true)
        );
        assert_eq!(desktop_reference("No banner."), "No banner.");
    }

    /// The committed file fits the budget the frontend generator enforces
    /// (`AGENT_UI_PROMPT_MAX_CHARS`), so the section never pushes another
    /// one out of the 40,000 character prompt.
    #[test]
    fn the_reference_fits_its_budget_and_is_ascii() {
        assert!(reference().len() <= 8800, "{}", reference().len());
        assert!(OPENUI_LANG_DOC.is_ascii());
    }
}
